library;

import '../../../core/utils/app_date_time_format.dart';
import 'attendance_review_models.dart';

/// Domain models representing the actual hardware-verified Supabase schema
/// for Raksha Kawach live attendance telemetry.

/// Real backend event types generated by ESP32-S3 and edge functions.
enum LiveEventType {
  morningBoarding('morning_boarding', 'Morning Boarding'),
  eveningBoarding('evening_boarding', 'Evening Boarding'),
  deboarding('deboarding', 'Deboarding');

  final String value;
  final String label;
  const LiveEventType(this.value, this.label);

  String get displayName => label;

  static LiveEventType fromString(String? val) {
    switch (val) {
      case 'morning_boarding':
        return LiveEventType.morningBoarding;
      case 'evening_boarding':
        return LiveEventType.eveningBoarding;
      case 'deboarding':
        return LiveEventType.deboarding;
      default:
        return LiveEventType.morningBoarding;
    }
  }
}

/// Anti-proxy phone proximity verification statuses.
/// Critical system rule: FLAG, NOT BLOCK.
enum LiveVerificationStatus {
  phonePresent(
    'phone_present',
    'Verified Nearby',
    'Student phone confirmed proximate to bus GPS',
  ),
  phoneNotNearby(
    'phone_not_nearby',
    'Proxy Warning',
    'Student phone was distant during scan',
  ),
  locationUnavailable(
    'location_unavailable',
    'Location Unavailable',
    'No recent phone GPS telemetry received',
  ),
  verificationUncertain(
    'verification_uncertain',
    'GPS Uncertain',
    'GPS accuracy too low for proximity calculation',
  );

  final String value;
  final String label;
  final String description;
  const LiveVerificationStatus(this.value, this.label, this.description);

  static LiveVerificationStatus fromString(String? val) {
    switch (val) {
      case 'phone_present':
        return LiveVerificationStatus.phonePresent;
      case 'phone_not_nearby':
        return LiveVerificationStatus.phoneNotNearby;
      case 'location_unavailable':
        return LiveVerificationStatus.locationUnavailable;
      case 'verification_uncertain':
        return LiveVerificationStatus.verificationUncertain;
      default:
        return LiveVerificationStatus.locationUnavailable;
    }
  }
}

/// Student profile resolved strictly from the verified `students` table.
class LiveStudentInfo {
  final String id;
  final String studentCode;
  final String studentName;
  final String? rfidUid;
  final String? schoolId;
  final DateTime? createdAt;
  final bool isBlocked;
  final int activeStrikes;
  final DateTime? blockedAt;
  final String? blockedReason;

  const LiveStudentInfo({
    required this.id,
    required this.studentCode,
    required this.studentName,
    this.rfidUid,
    this.schoolId,
    this.createdAt,
    this.isBlocked = false,
    this.activeStrikes = 0,
    this.blockedAt,
    this.blockedReason,
  });

  /// Displays the RFID identifier securely masked (e.g. `••• 4A8F`).
  String get maskedRfid {
    if (rfidUid == null || rfidUid!.trim().isEmpty) return 'No Card Linked';
    final clean = rfidUid!.trim();
    if (clean.length <= 4) return '••• $clean';
    return '••• ${clean.substring(clean.length - 4)}';
  }

  /// Policy-aligned strike label (e.g. `1/3 — Warning`, `3/3 — Card Blocked`).
  String get strikeStatusLabel {
    if (isBlocked || activeStrikes >= 3) {
      return '3/3 — Card Blocked';
    }
    switch (activeStrikes) {
      case 2:
        return '2/3 — Final Warning';
      case 1:
        return '1/3 — Warning';
      default:
        return '0/3 — Active';
    }
  }

  factory LiveStudentInfo.fromJson(Map<String, dynamic> json) {
    return LiveStudentInfo(
      id: json['id']?.toString() ?? '',
      studentCode: json['student_code']?.toString() ?? '',
      studentName: json['student_name']?.toString() ?? 'Unknown Student',
      rfidUid: json['rfid_uid']?.toString(),
      schoolId: json['school_id']?.toString(),
      createdAt: json['created_at'] != null
          ? DateTime.tryParse(json['created_at'].toString())
          : null,
      isBlocked: json['is_blocked'] == true,
      activeStrikes: (json['active_strikes'] as num?)?.toInt() ?? 0,
      blockedAt: json['blocked_at'] != null
          ? DateTime.tryParse(json['blocked_at'].toString())
          : null,
      blockedReason: json['blocked_reason']?.toString(),
    );
  }

  Map<String, dynamic> toJson() => {
    'id': id,
    'student_code': studentCode,
    'student_name': studentName,
    'rfid_uid': rfidUid,
    'school_id': schoolId,
    'created_at': createdAt?.toIso8601String(),
    'is_blocked': isBlocked,
    'active_strikes': activeStrikes,
    'blocked_at': blockedAt?.toIso8601String(),
    'blocked_reason': blockedReason,
  };
}

/// Real attendance record mapped strictly from the verified `attendance` table.
class LiveAttendanceRecord {
  final String id;
  final String studentId;
  final String? attendanceStatus;
  final DateTime scannedAt;
  final double? latitude;
  final double? longitude;
  final String? deviceId;
  final DateTime? createdAt;
  final LiveEventType eventType;
  final DateTime? eventDate;
  final LiveVerificationStatus verificationStatus;
  final double? phoneDistanceM;
  final DateTime? phoneLocationAt;
  final int? phoneLocationAgeSeconds;
  final double? phoneAccuracyM;

  /// Resolved student profile (via `students` lookup or join)
  final LiveStudentInfo? student;

  /// Administrative conflict review decision (if any)
  final AttendanceReviewRecord? review;

  /// Effective final attendance status resolved strictly from scan telemetry
  /// and explicit administrator adjudication.
  EffectiveAttendanceStatus get effectiveStatus =>
      EffectiveAttendanceResolver.resolveRecord(this, review: review);

  const LiveAttendanceRecord({
    required this.id,
    required this.studentId,
    this.attendanceStatus,
    required this.scannedAt,
    this.latitude,
    this.longitude,
    this.deviceId,
    this.createdAt,
    required this.eventType,
    this.eventDate,
    required this.verificationStatus,
    this.phoneDistanceM,
    this.phoneLocationAt,
    this.phoneLocationAgeSeconds,
    this.phoneAccuracyM,
    this.student,
    this.review,
  });

  factory LiveAttendanceRecord.fromJson(
    Map<String, dynamic> json, {
    LiveStudentInfo? resolvedStudent,
    AttendanceReviewRecord? review,
  }) {
    final embeddedStudent = json['students'] is Map<String, dynamic>
        ? LiveStudentInfo.fromJson(json['students'] as Map<String, dynamic>)
        : resolvedStudent;

    return LiveAttendanceRecord(
      id: json['id']?.toString() ?? '',
      studentId: json['student_id']?.toString() ?? '',
      attendanceStatus: json['attendance_status']?.toString(),
      scannedAt: json['scanned_at'] != null
          ? DateTime.tryParse(json['scanned_at'].toString()) ?? DateTime.now()
          : (json['created_at'] != null
                ? DateTime.tryParse(json['created_at'].toString()) ??
                      DateTime.now()
                : DateTime.now()),
      latitude: json['latitude'] != null
          ? double.tryParse(json['latitude'].toString())
          : null,
      longitude: json['longitude'] != null
          ? double.tryParse(json['longitude'].toString())
          : null,
      deviceId: json['device_id']?.toString(),
      createdAt: json['created_at'] != null
          ? DateTime.tryParse(json['created_at'].toString())
          : null,
      eventType: LiveEventType.fromString(json['event_type']?.toString()),
      eventDate: json['event_date'] != null
          ? DateTime.tryParse(json['event_date'].toString())
          : null,
      verificationStatus: LiveVerificationStatus.fromString(
        json['verification_status']?.toString(),
      ),
      phoneDistanceM: json['phone_distance_m'] != null
          ? double.tryParse(json['phone_distance_m'].toString())
          : null,
      phoneLocationAt: json['phone_location_at'] != null
          ? DateTime.tryParse(json['phone_location_at'].toString())
          : null,
      phoneLocationAgeSeconds: json['phone_location_age_seconds'] != null
          ? int.tryParse(json['phone_location_age_seconds'].toString())
          : null,
      phoneAccuracyM: json['phone_accuracy_m'] != null
          ? double.tryParse(json['phone_accuracy_m'].toString())
          : null,
      student: embeddedStudent,
      review: review,
    );
  }

  LiveAttendanceRecord copyWith({
    String? id,
    String? studentId,
    String? attendanceStatus,
    DateTime? scannedAt,
    double? latitude,
    double? longitude,
    String? deviceId,
    DateTime? createdAt,
    LiveEventType? eventType,
    DateTime? eventDate,
    LiveVerificationStatus? verificationStatus,
    double? phoneDistanceM,
    DateTime? phoneLocationAt,
    int? phoneLocationAgeSeconds,
    double? phoneAccuracyM,
    LiveStudentInfo? student,
    AttendanceReviewRecord? review,
  }) {
    return LiveAttendanceRecord(
      id: id ?? this.id,
      studentId: studentId ?? this.studentId,
      attendanceStatus: attendanceStatus ?? this.attendanceStatus,
      scannedAt: scannedAt ?? this.scannedAt,
      latitude: latitude ?? this.latitude,
      longitude: longitude ?? this.longitude,
      deviceId: deviceId ?? this.deviceId,
      createdAt: createdAt ?? this.createdAt,
      eventType: eventType ?? this.eventType,
      eventDate: eventDate ?? this.eventDate,
      verificationStatus: verificationStatus ?? this.verificationStatus,
      phoneDistanceM: phoneDistanceM ?? this.phoneDistanceM,
      phoneLocationAt: phoneLocationAt ?? this.phoneLocationAt,
      phoneLocationAgeSeconds:
          phoneLocationAgeSeconds ?? this.phoneLocationAgeSeconds,
      phoneAccuracyM: phoneAccuracyM ?? this.phoneAccuracyM,
      student: student ?? this.student,
      review: review ?? this.review,
    );
  }
}

/// Aggregated real-time metrics for the Overview Dashboard.
class LiveDashboardMetrics {
  final int totalToday;
  final int morningBoardingsToday;
  final int eveningBoardingsToday;
  final int deboardingsToday;
  final int verifiedNearbyToday;
  final int flaggedToday;
  final int pendingReviewToday;

  // Dedicated Effective Attendance Metric Counts (Anti-Proxy Adjudication)
  final int presentToday;
  final int underReviewToday;
  final int absentToday;
  final int contactTransportToday;

  const LiveDashboardMetrics({
    this.totalToday = 0,
    this.morningBoardingsToday = 0,
    this.eveningBoardingsToday = 0,
    this.deboardingsToday = 0,
    this.verifiedNearbyToday = 0,
    this.flaggedToday = 0,
    this.pendingReviewToday = 0,
    this.presentToday = 0,
    this.underReviewToday = 0,
    this.absentToday = 0,
    this.contactTransportToday = 0,
  });

  factory LiveDashboardMetrics.fromRecords(
    List<LiveAttendanceRecord> records, {
    Map<String, AttendanceReviewRecord>? reviews,
    DateTime? referenceDay,
  }) {
    final todayRecords = records.where((r) {
      return AppDateTimeFormat.isSameIstDay(r.scannedAt, referenceDay);
    }).toList();

    int morning = 0;
    int evening = 0;
    int deboarding = 0;
    int verifiedNearby = 0;
    int flagged = 0;

    int present = 0;
    int underReview = 0;
    int absent = 0;
    int contactTransport = 0;

    for (final r in todayRecords) {
      switch (r.eventType) {
        case LiveEventType.morningBoarding:
          morning++;
          break;
        case LiveEventType.eveningBoarding:
          evening++;
          break;
        case LiveEventType.deboarding:
          deboarding++;
          break;
      }

      if (r.verificationStatus == LiveVerificationStatus.phonePresent) {
        verifiedNearby++;
      } else {
        flagged++;
      }

      // Resolve effective attendance outcome
      final effective = EffectiveAttendanceResolver.resolveRecord(
        r,
        review: r.review ?? reviews?[r.id],
      );
      switch (effective) {
        case EffectiveAttendanceStatus.present:
          present++;
          break;
        case EffectiveAttendanceStatus.underReview:
          underReview++;
          break;
        case EffectiveAttendanceStatus.absent:
          absent++;
          break;
        case EffectiveAttendanceStatus.contactTransport:
          contactTransport++;
          break;
      }
    }

    return LiveDashboardMetrics(
      totalToday: todayRecords.length,
      morningBoardingsToday: morning,
      eveningBoardingsToday: evening,
      deboardingsToday: deboarding,
      verifiedNearbyToday: verifiedNearby,
      flaggedToday: flagged,
      pendingReviewToday: flagged,
      presentToday: present,
      underReviewToday: underReview,
      absentToday: absent,
      contactTransportToday: contactTransport,
    );
  }
}

/// Represents an ESP32-S3 hardware unit observed through attendance scans.
class ObservedHardwareUnit {
  final String deviceId;
  final DateTime lastSeenAt;
  final String lastEventType;
  final double? lastLatitude;
  final double? lastLongitude;

  const ObservedHardwareUnit({
    required this.deviceId,
    required this.lastSeenAt,
    required this.lastEventType,
    this.lastLatitude,
    this.lastLongitude,
  });
}
